import{_ as e,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-10-01 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-10-01 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-10-01T00:00:00.000Z","updated":"2019-10-03T00:00:00.000Z","tags":["Ceph","Distributed Storage","Blue Store","Performance Optimization","Storage Engine"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-01_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-10-01_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-10-01_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function s(n,t,g,a,p,_){return l(),i("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Jim, Riddick, Sage, 其他研发人员</p><p><strong>会议主题</strong>： Ceph分布式存储系统研发讨论</p><p><strong>主要议题及讨论内容</strong>：</p><p><strong>1. Blue Store性能问题及解决方案</strong></p><ul><li><strong>问题</strong>： Blue Store在处理较慢的硬盘和SSD时存在性能问题，可能会增加开销。</li><li><strong>解决方案</strong>： <ul><li>长期计划是使用新的存储系统来支持高性能设备，Blue Store主要针对硬盘和较慢的SSD。</li><li>在短期，如果Blue Store能够带来显著的性能提升，即使增加一些开销也是值得的。</li><li>需要评估在Blue Store中引入伊利诺伊州加速器的努力是否值得。</li></ul></li></ul><p><strong>2. Ceph存储引擎优化</strong></p><ul><li><strong>议题</strong>： 对Ceph存储引擎进行优化，提高性能。</li><li><strong>讨论内容</strong>： <ul><li>Jim正在更新现有分支，优化存储引擎性能。</li><li>已经将socket系统中的注册数据结构进行了优化，避免了不必要的开销。</li><li>正在研究如何实现socket系统，并尝试使用Gaussian数据结构来维护注册信息。</li></ul></li></ul><p><strong>3. Ceph对象存储调度器</strong></p><ul><li><strong>议题</strong>： 开发Ceph对象存储调度器，提高系统性能。</li><li><strong>讨论内容</strong>： <ul><li>正在实现背景恢复功能，并使用Crimson进行调度。</li><li>将实现对象读写锁定，并修改接口以支持不同的锁定策略。</li><li>需要实现对象状态增长，以支持更复杂的锁定机制。</li></ul></li></ul><p><strong>4. Ceph配置选项</strong></p><ul><li><strong>议题</strong>： 为Ceph配置系统添加新的配置选项，以支持调度器和其他功能。</li><li><strong>讨论内容</strong>： <ul><li>将在Crimson中添加新的实验性配置选项，用于控制调度器和对象读写锁定等功能。</li><li>将使用注释或标签来标识这些实验性选项，以避免在生产环境中使用。</li></ul></li></ul><p><strong>5. Ceph与其他存储系统的兼容性</strong></p><ul><li><strong>议题</strong>： 与Percy Store进行兼容性测试。</li><li><strong>讨论内容</strong>： <ul><li>需要阅读Percy Store的初步草案，并制定兼容性测试计划。</li><li>将在Google文档中记录设计方向、问题和目标，以便讨论。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Jim继续优化Ceph存储引擎。</li><li>开发Ceph对象存储调度器，并实现对象读写锁定。</li><li>为Ceph配置系统添加新的实验性配置选项。</li><li>与Percy Store进行兼容性测试。</li></ul>',17)])])}const c=e(r,[["render",s]]);export{S as __pageData,c as default};
